import{_ as p,a0 as q,w as r,s as k,ao as n,I as e,x as o,a1 as a,A as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"也许是有史以来最好的游戏：NetHack | LCTT x X-CMD","titleTemplate":false,"description":"也许是有史以来最好的游戏：NetHack | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"也许是有史以来最好的游戏：NetHack | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"也许是有史以来最好的游戏：NetHack | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141211 NetHack","title":"也许是有史以来最好的游戏：NetHack","tag":"201501","desc":""},"relativePath":"201501/20141211 NetHack.md","filePath":"[post].md"}'),i={name:"201501/20141211 NetHack.md"};function s(d,t,m,N,w,H){const u=q("Link");return r(),k("div",null,[t[24]||(t[24]=n('<h1 id="也许是有史以来最好的游戏-nethack" tabindex="-1">也许是有史以来最好的游戏：NetHack <a class="header-anchor" href="#也许是有史以来最好的游戏-nethack" aria-label="Permalink to “也许是有史以来最好的游戏：NetHack”">​</a></h1><p><strong>这款游戏非常容易让你上瘾。你可能需要花费一生的时间来掌握它。许多人玩了几十年也没有通关。欢迎来到 NetHack 的世界...</strong></p><p>不管你信不信，在 NetHack 里你见到字母 <strong>D</strong> 的时候你会被吓着。但是当你看见一个 <strong>%</strong> 的时候，你将会欣喜若狂。（忘了说 <strong>^</strong>，你看见它将会更激动）在你寻思我们的脑子是不是烧坏了并准备关闭浏览器标签之前，请给我们一点时间解释：这些符号分别代表龙、食物以及陷阱。欢迎来到 NetHack 的世界，在这里你的想象力需要发挥巨大的作用。</p><p>如你所见，NetHack 是一款文字模式的游戏：它仅仅使用标准终端字符集来刻画玩家、敌人、物品还有环境。游戏的图形版是存在的，不过 NetHack 的骨灰级玩家们都倾向于不去使用它们，问题在于假如你使用图形界面，当你通过 SSH 登录到你的古董级的运行着 NetBSD 的 Amiga 3000 上时，你还能进行游戏吗？在某些方面，NetHack 和 Vi 非常相似 - 几乎被移植到了现存的所有的操作系统上，并且依赖都非常少。</p><p>那么问题来了，和现代游戏相比如此简陋的画面，是什么造就了 NetHack 如此巨大的吸引力的呢？ 事实上，这款地牢探险类神作有着令人难以置信的丰富细节。有太多的东西等着你去发掘：法术释放、怪物战斗以及技巧学习 - 以及随机生成的地牢。有太多的东西等着你去探索，几乎没有哪两局游戏会是完全一样的。许多人玩了几十年也没有通关，每次游戏依然能发现一些以前不知道的秘密。</p><p>接下来，我们会向你讲述 NetHack 的历史，给你地牢探险的基本指导，再告诉你一些技巧。免责： 在你继续阅读本文之前，视为你已经自动同意了当你沉溺于 NetHack 以致影响到你的现实生活时，你不会起诉我们。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/12/nh_annotated.png" alt="NetHack 界面"></p><p><em>NetHack 界面</em></p><h3 id="也许是最古老的仍在开发的游戏里" tabindex="-1">也许是最古老的仍在开发的游戏里 <a class="header-anchor" href="#也许是最古老的仍在开发的游戏里" aria-label="Permalink to “也许是最古老的仍在开发的游戏里”">​</a></h3>',9)),e("p",null,[t[1]||(t[1]=o("名非其实，NetHack 并不是一款网络游戏。它只不过是基于一款出现较早的名为 Hack 的地牢探险类游戏开发出来的，而这款 Hack 游戏是 1980 年的游戏 Rogue 的后代。NetHack 在 1987 年发布了第一个版本，并于 2003 年发布了 3.4.3 版本，尽管在这期间一直没有加入新的功能，但各种补丁、插件，以及衍生作品还是在网络上疯狂流传。这使得它可以说是最古老的、拥有众多对游戏乐此不疲的粉丝的游戏。当你访问 ",-1)),a(u,{href:"http://www.reddit.com/r/nethack"},{default:l(()=>[...t[0]||(t[0]=[o("www.reddit.com/r/nethack",-1)])]),_:1}),t[2]||(t[2]=o(" 之后，你就会了解我们的意思了 - 骨灰级的 NetHack 的玩家们仍然聚集在一起讨论新的策略、发现和技巧。偶尔你也可以发现 NetHack 的元老级玩家在历经千辛万苦终于通关之后发出的欢呼。",-1))]),t[25]||(t[25]=e("p",null,"但怎样才能通关呢？首先，NetHack 被设定在既大又深的地牢中。游戏开始时你在最顶层 - 第 1 层 - 你的目标是不断往下深入直到你找到一个非常宝贵的物品，护身符 Yendor。通常来说 Yendor 在 第 20 层或者更深的地方，但它是可以变化的。随着你在地牢的不断深入，你会遇到各种各样的怪物、陷阱以及 NPC；有些会试图杀掉你，有些会挡在你前进的路上，还有些... 总而言之，在你靠近 TA 们之前你永远不知道 TA 们会怎样。",-1)),t[26]||(t[26]=e("blockquote",null,[e("p",null,"要学习的有太多太多，绝大多数物品只有在和其他物品同时使用的情况下才会发挥最好的效果。")],-1)),t[27]||(t[27]=e("p",null,"使 NetHack 如此引人入胜的原因是游戏中所加入的大量物品。武器、盔甲、附魔书、戒指、宝石 - 要学习的有太多太多，绝大多数物品只有在和其他物品同时使用的情况下才会发挥最好的效果。怪物在死亡后经常会掉落一些有用的物品，以及某些物品如果你不正确使用的话会产生及其不良的作用。你可以在地牢找到商店，里面有许多看似平凡实则非常有用的物品，不过别指望店主能给你详细的描述。你只能靠自己的经验来了解各个物品的用途。有些物品确实没有太大用处，NetHack 中有很多的恶搞元素 - 比如你可以把一块奶油砸到自己的脸上。",-1)),t[28]||(t[28]=e("p",null,"不过在你踏入地牢之前，NetHack 会询问你要选择哪种角色进行游戏。你可以为你接下来的地牢之行选择骑士、修道士、巫师，或者卑微的旅者，还有许多其他的角色类型。每种角色都有其独特的优势与弱点，NetHack 的重度玩家喜欢选择那些相对较弱的角色来挑战游戏。你懂的，这样可以向其他玩家炫耀自己的实力。",-1)),t[29]||(t[29]=e("blockquote",null,[e("p",null,[e("strong",null,"情报不会降低游戏的乐趣")])],-1)),t[30]||(t[30]=e("blockquote",null,[e("p",null,"用 NetHack 的说法来讲，“情报员”给指其他玩家提供关于怪物、物品、武器和盔甲信息的玩家。理论上来说，完全可以不借助任何外来信息而通关，但几乎没有几个玩家能做到，游戏实在是太难了。因此使用情报并不会被视为一件糟糕的事情 - 但是一开始由你自己来探索游戏和解决难题，这样才会获得更多的乐趣，只有当你遇到瓶颈的时候再去使用那些情报。")],-1)),e("blockquote",null,[e("p",null,[t[4]||(t[4]=o("在这里给出一个比较有名的情报站点 ",-1)),a(u,{href:"http://www.statslab.cam.ac.uk/~eva/nethack/spoilerlist.html"},{default:l(()=>[...t[3]||(t[3]=[o("www.statslab.cam.ac.uk/~eva/nethack/spoilerlist.html",-1)])]),_:1}),t[5]||(t[5]=o("，其中的情报被分为了不同的类别。游戏中随机发生的事，比如在喷泉旁饮水可能导致的不同结果，从这里你可以得知已确定的不同结果的发生概率。",-1))])]),t[31]||(t[31]=n('<h3 id="你的首次地牢之行" tabindex="-1">你的首次地牢之行 <a class="header-anchor" href="#你的首次地牢之行" aria-label="Permalink to “你的首次地牢之行”">​</a></h3><p>NetHack 几乎可以在所有的主流操作系统以及 Linux 发行版上运行，因此你可以通过 &quot;apt-get install nethack&quot; 或者 &quot;yum install nethack&quot; 等适合你用的发行版的命令来安装游戏。安装完毕后，在一个命令行窗口中键入 &quot;nethack&quot; 就可以开始游戏了。游戏开始时系统会询问是否为你随机挑选一位角色 - 但作为一个新手，你最好自己从里面挑选一位比较强的角色。所以，你应该点 &quot;n&quot;，然后点 &quot;v&quot; 以选取女武神（Valkyrie），而点 &quot;d&quot; 会选择成为侏儒（dwarf）。</p><p>接着 NetHack 上会显示出剧情，说你的神正在寻找护身符 Yendor，你的目标就是找到它并将它带给神。阅读完毕后点击空格键（其他任何时候当你见到屏幕上的 &quot;-More-&quot; 时都可以这样）。接着就让我们出发 - 开始地牢之行吧！</p><p>先前已经介绍过了，你的角色用 @ 来表示。你可以看见角色所出房间周围的墙壁，房间里显示“点”的那些地方是你可以移动的空间。首先，你得明白怎样移动角色：h、j、k 以及 l。（是的，和 Vim 中移动光标的操作相同）这些操作分别会使角色向向左、向下、向上以及向右移动。你也可以通过 y、u、b 和 n 来使角色斜向移动。在你熟悉如何控制角色移动前你最好在房间里来回移动你的角色。</p><p>NetHack 采用了回合制，因此即使你不进行任何动作，游戏仍然在进行。这是你可以提前计划你的行动。你可以看见一个 &quot;d&quot; 字符或者 &quot;f&quot; 字符在房间里来回移动：这是你的宠物狗/猫，（通常情况下）它们不会伤害你而是帮助你击杀怪物。但是宠物也会被惹怒 - 它们偶尔也会抢在你接近食物或者怪物尸体之前吃掉它们。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/12/nh_inventory.png" alt="点击 “i” 列出你当前携带的物品清单"></p><p><em>点击 “i” 列出你当前携带的物品清单</em></p><h3 id="门后有什么" tabindex="-1">门后有什么？ <a class="header-anchor" href="#门后有什么" aria-label="Permalink to “门后有什么？”">​</a></h3><p>接下来，让我们离开房间。房间四周的墙壁某处会有缝隙，可能是 &quot;+&quot; 号。&quot;+&quot; 号表示一扇关闭的门，这时你应该靠近它然后点击 &quot;o&quot; 来开门。接着系统会询问你开门的方向，假如门在你的左方，就点击 &quot;h&quot;。（如果门被卡住了，就多试几次）然后你就可以看见门后的走廊了，它们由 &quot;#&quot; 号表示，沿着走廊前进直到你找到另一个房间。</p><p>地牢之行中你会见到各种各样的物品。某些物品，比如金币（由 &quot;$&quot; 号表示）会被自动捡起来；至于另一些物品，你只能站在上面按下逗号键手动拾起。如果同一位置有多个物品，系统会给你显示一个列表，你只要通过合适的按键选择列表中你想要的物品最后按下 &quot;Enter&quot; 键即可。任何时间你都可以点击 &quot;i&quot; 键在屏幕上列出你当前携带的物品清单。</p><p>如果看见了怪物该怎么办？在游戏早期，你可能会遇到的怪物会用符号 &quot;d&quot;、&quot;x&quot; 和 &quot;:&quot; 表示。想要攻击的话，只要简单地朝怪物的方向移动即可。系统会在屏幕顶部通过信息显示来告诉你攻击是否成功 - 以及怪物做出了何种反应。早期的怪物很容易击杀，所以你可以毫不费力地打败他们，但请留意底部状态栏里显示的角色的 HP 值。</p><blockquote><p>早期的怪物很容易击杀，但请留意角色的 HP 值。</p></blockquote><p>如果怪物死后掉落了一具尸体（&quot;%&quot;），你可以点击逗号进行拾取，并点击 &quot;e&quot; 来食用。（在任何时候系统提示你选择一件物品，你都可以从物品列表中点击相应的按键，或者点击 &quot;?&quot; 来查询迷你菜单。）注意！有些尸体是有毒的，这些知识你将在日后的冒险中逐渐学会掌握。</p><p>如果你在走廊里行进时遇到了死胡同，你可以点击 &quot;s&quot; 进行搜寻直到找到一扇门。这会花费时间，但是你可以这样加速游戏进程：输入 &quot;10&quot; 并点击 &quot;s&quot; 你将一下搜索 10 次。这将花费游戏中进行 10 次动作的时间，不过如果你正在饥饿状态，你将有可能会被饿死！</p><p>通常你可以在地牢顶部找到 &quot;{&quot;（喷泉）以及 &quot;!&quot;（药水）。当你找到喷泉的时候，你可以站在上面并点击 &quot;q&quot; 键开始 “畅饮（quaff）” - 引用后会得到从振奋的到致命的多种效果。当你找到药水的时候，将其拾起并点击 &quot;q&quot; 来饮用。如果你找到一个商店，你可以拾取其中的物品并在离开前点击 &quot;p&quot; 键进行支付。当你负重过大时，你可以点击 &quot;d&quot; 键丢掉一些东西。</p><p><img src="http://www.linuxvoice.com/wp-content/uploads/2014/12/falcon.jpg" alt="现在已经有带音效的 3D 版 Nethack 了，如：Falcon’s Eye"></p><p><em>现在已经有带音效的 3D 版 Nethack 了，如：Falcon’s Eye</em></p><blockquote><p><strong>愚蠢的死法</strong></p></blockquote><blockquote><p>在 NetHack 玩家中流行着一个缩写词 &quot;YASD&quot; - 又一种愚蠢的死法（Yet Another Stupid Death）。这个缩写词表示了玩家由于自身的的愚蠢或者粗心大意导致了角色的死亡。我们搜集了很多这类死法，但我们最喜欢的是下面这种死法：</p></blockquote><blockquote><p>我们正在商店浏览商品，这时一条蛇突然从药剂后面跳了出来。在杀死蛇之后，系统弹出一条信息提醒我们角色饥饿值过低了，因此我们顺手食用了蛇的尸体。坏事了！这使得我们的角色失明，导致我们的角色再也不能看见商店里的其他角色及地上的商品了。我们试图离开商店，但在慌乱中却撞在了店主身上并攻击了他。这种做法激怒了店主：他立即向我们的角色使用了火球术。我们试图逃到商店外的走廊上，但却在逃亡的过程中被烧死。</p></blockquote><blockquote><p>如果你有类似的死法，一定要来我们的论坛告诉我们。不要担心 - 没有人会嘲笑你。经历这样的死法也是你在 NetHack 的世界里不断成长的一部分。哈哈。</p></blockquote><h3 id="武装自己" tabindex="-1">武装自己 <a class="header-anchor" href="#武装自己" aria-label="Permalink to “武装自己”">​</a></h3><p>地牢里，尤其是在你击杀怪物后，你可能会发现武器或盔甲。在这里再说一次，点击逗号把它们拾起，接着点击 &quot;w&quot;（小写的）来使用武器或者点击 &quot;W&quot;（大写的）来穿上盔甲。你可以用 &quot;T&quot; 来脱掉盔甲或者 &quot;t&quot; 来取下武器 - 如果你陷入了困境，请确保你总是在使用最好的装备。</p><p>在靠近掉在地下的装备之前最好检查一下身上的东西。点击 &quot;;&quot;（分号）后，&quot;Pick an object&quot;（选择一样物品）选项将出现在屏幕顶部。选择该选项，使用移动键直到选中你想要检查的物品，然后点击 &quot;:&quot;（冒号）。接着屏幕顶部将出现这件物品的描述。</p><p>因为你的目标是不断深入地牢直到找到护身符 Yendor，所以请随时留意周围的 &quot;&lt;&quot; 和 &quot;&gt;&quot; 符号。这两个符号分别表示向上和向下的楼梯，你可以用与之对应的按键来上楼或下楼。注意！如果你想让宠物跟随你进入下/上一层地牢，下/上楼前请确保你的宠物在你邻近的方格内。若果你想退出，点击 &quot;S&quot;（大写的）来保存进度，输入 #quit 退出游戏。当你再次运行 NetHack 时，系统将会自动读取你上次退出时的游戏进度。</p>',25)),e("p",null,[t[8]||(t[8]=o("我们就不继续剧透了，地牢深处还有更多的神秘细节、陌生的 NPC 以及不为人知的秘密等着你去发掘。那么，我们再给你点建议：当你遇到了让你困惑不已的物品时，你可以尝试去 NetHack 维基 ",-1)),a(u,{href:"http://nethack.wikia.com/"},{default:l(()=>[...t[6]||(t[6]=[o("http://nethack.wikia.com",-1)])]),_:1}),t[9]||(t[9]=o(" 进行搜索。你也可以在 ",-1)),a(u,{href:"http://www.nethack.org/v343/Guidebook.html"},{default:l(()=>[...t[7]||(t[7]=[o("www.nethack.org/v343/Guidebook.html",-1)])]),_:1}),t[10]||(t[10]=o(" 找到一本非常不错（尽管很长）的指导手册。最后，祝游戏愉快！",-1))]),t[32]||(t[32]=e("hr",null,null,-1)),e("p",null,[t[12]||(t[12]=o("via: ",-1)),a(u,{href:"http://www.linuxvoice.com/nethack/"},{default:l(()=>[...t[11]||(t[11]=[o("http://www.linuxvoice.com/nethack/",-1)])]),_:1})]),e("p",null,[t[16]||(t[16]=o("作者：",-1)),a(u,{href:"http://www.linuxvoice.com/author/mike/"},{default:l(()=>[...t[13]||(t[13]=[o("Mike Saunders",-1)])]),_:1}),t[17]||(t[17]=o(" 译者：",-1)),a(u,{href:"https://github.com/Stevearzh"},{default:l(()=>[...t[14]||(t[14]=[o("Stevearzh",-1)])]),_:1}),t[18]||(t[18]=o(" 校对：",-1)),a(u,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),e("p",null,[t[21]||(t[21]=o("本文由 ",-1)),a(u,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原创翻译，",-1)),a(u,{href:"http://linux.cn/"},{default:l(()=>[...t[20]||(t[20]=[o("Linux中国",-1)])]),_:1}),t[23]||(t[23]=o(" 荣誉推出",-1))])])}const g=p(i,[["render",s]]);export{T as __pageData,g as default};
